use super::*;
use crate::settings::EffectFixture;
fn context(s:&Settings,p:&Path)->std::io::Result<Context>{let mut c=native_context(s,p)?;c.profile=Some(hash(p.parent().unwrap().as_os_str().as_encoded_bytes()));Ok(c)}
struct Fixture{files:EffectFixture,controller:Controller,owner:settings::review::Controller,frame:Frame,alive:Arc<AtomicBool>}
impl Fixture{
 fn new()->Self{let files=EffectFixture::new();files.save();let owner=settings::review::Controller::default();owner.register();let frame=owner.frame().unwrap();Self{files,controller:Controller::default(),owner,frame,alive:Arc::new(AtomicBool::new(true))}}
 fn native(&self,instance:&str)->NativeCapture{let alive=self.alive.clone();NativeCapture{destination:Destination::Plugin{instance:instance.repeat(32),owner:process::capture().unwrap(),environment:Environment{display:Some(":99".into()),wayland_display:None,session_type:Some("x11".into())},previous:vec![]},current:Box::new(move||alive.load(Ordering::Acquire))}}
 fn uncertain(&self)->components::Slot{let p=self.controller.prepare_with(&self.frame,&self.files.current,&self.files.path,context,|_|Ok(self.native("a"))).unwrap();let d=super::super::Decision{token:p.token,fingerprint:p.fingerprint,reviewed_plan:true,understand_native_effects:true,keep_other_components_suspended:true,preview_schema_version:None,acknowledge_retained_uncertainty:false};self.controller.apply_with(&self.frame,&self.files.current,d,context,Arc::new(||true),|_,_,_|NativeRun{outcome:crate::portal::review::Outcome{verified:true,native_effects_started:true,reason:"synthetic native scope".into(),session:None,shortcuts:Some(vec![])},finish:Some(Box::new(|_,_|Publication::refused(None)))}).unwrap();context(&self.files.current.lock().unwrap(),&self.files.path).unwrap().slot.unwrap()}
 fn prepare(&self,ready:bool)->Preview{self.controller.prepare_reconciliation(&self.frame,&self.files.current,&self.files.path,context,|_|Ok(self.native("a")),|_,_,_|Ok(observation(ready))).unwrap()}
 fn decision(p:&Preview)->Decision{Decision{token:p.token.clone(),fingerprint:p.fingerprint.clone(),preview_schema_version:2,reviewed_observation:true,understand_past_uncertainty:true,keep_registration_suspended:true}}
 fn apply(&self,p:&Preview,ready:bool)->Result<Receipt,String>{self.controller.apply_reconciliation(&self.frame,&self.files.current,Self::decision(p),context,Arc::new(||true),|_,_,_|Ok(observation(ready)))}
}
fn observation(ready:bool)->Observation{Observation{schema_version:1,current_instance:"a".repeat(32),current_process:process::capture().unwrap(),current_environment:Environment{display:Some(":99".into()),wayland_display:None,session_type:Some("x11".into())},current_transport:"plugin".into(),original_instance:Some("a".repeat(32)),original_process:Some(ProcessPresence::OriginalLive),same_instance:true,can_reconcile:ready,reason:"synthetic bounded native close observation".into(),portal:None,plugin_cleanup_acknowledged:Some(ready)}}
#[test]fn shortcut_original_owner_comparison_is_retained_and_old_controls_cannot_confirm_it(){
 let f=Fixture::new();let slot=f.uncertain();let p=f.prepare(true);assert_eq!(p.schema_version,2);
 let(_,intent,_)=components::current_artifacts(&f.files.current.lock().unwrap(),&f.files.path,"shortcuts").unwrap().unwrap();let shown=serde_json::to_value(&p.original).unwrap();let native=&intent.evidence["review"]["destination"];
 for key in["instance","owner","environment","kind"]{assert_eq!(shown[key],native[key]);}assert_eq!(shown["portal"],serde_json::Value::Null);
 let current=serde_json::to_value(&p.current).unwrap();assert_eq!(current["owner"],serde_json::to_value(&p.observation.current_process).unwrap());assert_eq!(current["environment"],serde_json::to_value(&p.observation.current_environment).unwrap());assert_eq!(current["instance"],p.observation.current_instance);assert_eq!(current["kind"],p.observation.current_transport);
 let legacy=serde_json::json!({"token":p.token,"fingerprint":p.fingerprint,"reviewedObservation":true,"understandPastUncertainty":true,"keepRegistrationSuspended":true});assert!(serde_json::from_value::<Decision>(legacy).is_err());
 let before=std::fs::read(f.files.root.join(settings::durable::FILE)).unwrap();for version in[0,1,3]{let mut decision=Fixture::decision(&p);decision.preview_schema_version=version;assert!(f.controller.apply_reconciliation(&f.frame,&f.files.current,decision,context,Arc::new(||true),|_,_,_|panic!("stale control reached observation")).is_err());}assert_eq!(std::fs::read(f.files.root.join(settings::durable::FILE)).unwrap(),before);
 f.apply(&p,true).unwrap();let(slot_after,_,outcome)=components::current_artifacts(&f.files.current.lock().unwrap(),&f.files.path,"shortcuts").unwrap().unwrap();assert_eq!(slot_after.id,slot.id);let evidence=outcome.unwrap().evidence;assert_eq!(evidence["review"]["original"],shown);assert_eq!(evidence["review"]["current"],current);assert_eq!(evidence["review"]["schemaVersion"],2);
}
#[test]fn shortcut_current_portal_comparison_shows_known_session_not_the_uncreated_reserved_token(){
 let current=|phase,session|current_subject(&Destination::Portal{instance:"a".repeat(32),owner:process::capture().unwrap(),environment:Environment{display:Some(":99".into()),wayland_display:None,session_type:Some("wayland".into())},reservation:crate::portal::Reservation{generation:2,bus_id:"b".repeat(32),peer:":1.10".into(),client:":1.20".into(),session:"/org/freedesktop/portal/desktop/session/1_20/reserved_not_created".into(),create_request:"/fixture/c1".into(),bind_request:"/fixture/b1".into(),shortcuts:vec![],previous:crate::portal::review::Before{phase,generation:Some("1".into()),session,request:None,shortcuts:vec![],accepted:None}}});
 let active="/org/freedesktop/portal/desktop/session/1_20/known_bound".to_string();assert_eq!(current("bound",Some(active.clone())).portal.unwrap().sessions,vec![active]);assert!(current("idle",None).portal.unwrap().sessions.is_empty());
}
#[test]fn shortcut_reconciliation_refuses_to_publish_new_semantics_under_a_legacy_reader_version(){
 let f=Fixture::new();let old=f.uncertain();let journal=f.files.root.join(settings::durable::FILE);let mut v:serde_json::Value=serde_json::from_slice(&std::fs::read(&journal).unwrap()).unwrap();assert_eq!(v["version"],7);v["version"]=serde_json::json!(6);std::fs::write(&journal,serde_json::to_vec(&v).unwrap()).unwrap();*f.files.current.lock().unwrap()=settings::load_from(&f.files.path);let before=std::fs::read(&journal).unwrap();let p=f.prepare(true);let error=f.apply(&p,true).err().expect("legacy semantics cannot admit reconciliation");assert!(error.contains("componentShortcutObservationVersion"),"{error}");assert_eq!(std::fs::read(&journal).unwrap(),before);assert_eq!(context(&f.files.current.lock().unwrap(),&f.files.path).unwrap().slot.unwrap(),old);
}
#[test]fn shortcut_reconciliation_records_observation_without_registration_and_requires_a_distinct_new_review(){
 let f=Fixture::new();let old=f.uncertain();let settings=std::fs::read(&f.files.path).unwrap();let p=f.prepare(true);let receipt=f.apply(&p,true).unwrap();assert!(receipt.observation_recorded&&receipt.no_registration_effect&&receipt.no_reactivation&&!receipt.past_effect_outcome_known);assert_eq!(std::fs::read(&f.files.path).unwrap(),settings);assert!(receipt.status.suspended_operations.iter().any(|s|s=="shortcuts"));
 let(slot,_,outcome)=components::current_artifacts(&f.files.current.lock().unwrap(),&f.files.path,"shortcuts").unwrap().unwrap();assert_eq!(slot.id,old.id);assert_eq!(slot.phase,components::Phase::ReconciledObservation);assert_eq!(outcome.unwrap().evidence["subject"],serde_json::to_value(&old).unwrap());assert!(f.apply(&p,true).is_err());
 let next=f.controller.prepare_with(&f.frame,&f.files.current,&f.files.path,context,|_|Ok(f.native("a"))).unwrap();assert_ne!(next.token,p.token);assert_ne!(next.token,old.id);assert!(!next.activation_allowed);
}
#[test]fn shortcut_reconciliation_unavailable_observation_or_changed_native_fact_cannot_clear_the_pending_effect(){
 for ready in [false,true]{let f=Fixture::new();let old=f.uncertain();let p=f.prepare(ready);assert!(f.apply(&p,false).is_err());assert_eq!(context(&f.files.current.lock().unwrap(),&f.files.path).unwrap().slot.unwrap(),old);}
}
#[test]fn shortcut_reconciliation_requires_three_acknowledgements_and_refuses_scope_overrides(){
 let f=Fixture::new();let old=f.uncertain();let p=f.prepare(true);
 for n in 0..3{let mut d=Fixture::decision(&p);match n{0=>d.reviewed_observation=false,1=>d.understand_past_uncertainty=false,_=>d.keep_registration_suspended=false};assert!(f.controller.apply_reconciliation(&f.frame,&f.files.current,d,context,Arc::new(||true),|_,_,_|panic!("unapproved observation accepted")).is_err());}
 for field in ["caller","subject","owner","busId"]{let mut v=serde_json::json!({"token":p.token,"fingerprint":p.fingerprint,"previewSchemaVersion":2,"reviewedObservation":true,"understandPastUncertainty":true,"keepRegistrationSuspended":true});v[field]=serde_json::json!("forged");assert!(serde_json::from_value::<Decision>(v).is_err());}assert_eq!(context(&f.files.current.lock().unwrap(),&f.files.path).unwrap().slot.unwrap(),old);
}
#[test]fn shortcut_reconciliation_wrong_frame_source_native_epoch_and_expiry_are_refused_and_cancel_never_writes(){
 for mode in 0..5{let f=Fixture::new();let old=f.uncertain();let p=f.prepare(true);
 match mode{0=>{f.owner.register();},1=>f.files.update(|s|s.sound_volume=0.3),2=>f.alive.store(false,Ordering::Release),3=>f.controller.reconciliation.lock().unwrap().as_mut().unwrap().expires=Instant::now()-Duration::from_secs(1),_=>{f.controller.cancel(&f.frame,Key{token:p.token.clone(),fingerprint:p.fingerprint.clone()}).unwrap();}}
 assert!(f.apply(&p,true).is_err());assert_eq!(context(&f.files.current.lock().unwrap(),&f.files.path).unwrap().slot.unwrap(),old);}
}
#[test]fn shortcut_reconciliation_keeps_previous_native_result_hash_and_does_not_transfer_to_another_instance(){
 let f=Fixture::new();let old=f.uncertain();let p=f.prepare(true);f.apply(&p,true).unwrap();assert!(f.controller.prepare_with(&f.frame,&f.files.current,&f.files.path,context,|_|Ok(f.native("b"))).is_err());
 let reference=old.outcome.unwrap();std::fs::write(f.files.root.join(components::DIRECTORY).join(format!("component-{}.json",reference.id)),b"altered previous pending fact").unwrap();assert!(!settings::io_status(&f.files.current.lock().unwrap()).new_effects_allowed);let restarted=settings::load_from(&f.files.path);assert!(!settings::io_status(&restarted).new_effects_allowed);
}
#[test]fn shortcut_reconciliation_registration_preview_and_observation_preview_supersede_each_other(){
 let f=Fixture::new();f.uncertain();let p=f.prepare(true);f.apply(&p,true).unwrap();let second=f.prepare(true);let registration=f.controller.prepare_with(&f.frame,&f.files.current,&f.files.path,context,|_|Ok(f.native("a"))).unwrap();assert!(f.apply(&second,true).is_err());let third=f.prepare(true);assert!(f.controller.inspect_with(&f.frame,&f.files.current,&Key{token:registration.token,fingerprint:registration.fingerprint},context).is_err());f.controller.cancel(&f.frame,Key{token:third.token,fingerprint:third.fingerprint}).unwrap();
}

#[test]fn shortcut_reconciled_observation_does_not_transfer_to_another_display_or_transport_with_the_same_nonce(){
 let f=Fixture::new();f.uncertain();let p=f.prepare(true);f.apply(&p,true).unwrap();
 let mut changed=f.native("a");if let Destination::Plugin{environment,..}=&mut changed.destination{environment.display=Some(":100".into());}assert!(f.controller.prepare_with(&f.frame,&f.files.current,&f.files.path,context,|_|Ok(changed)).is_err());
 let mut changed=f.native("a");changed.destination=Destination::Portal{instance:"a".repeat(32),owner:process::capture().unwrap(),environment:Environment{display:Some(":99".into()),wayland_display:None,session_type:Some("x11".into())},reservation:crate::portal::Reservation{generation:1,bus_id:"e".repeat(32),peer:":1.10".into(),client:":1.20".into(),session:"/fixture/s1".into(),create_request:"/fixture/c1".into(),bind_request:"/fixture/b1".into(),shortcuts:vec![],previous:crate::portal::review::Before::idle()}};assert!(f.controller.prepare_with(&f.frame,&f.files.current,&f.files.path,context,|_|Ok(changed)).is_err());
}
